async function upsertAuthor(a) {
  let doc = await Author.findOne({ name: a.name });
  if (!doc) {
    doc = await Author.create(a);
    console.log(`[Author] Created: ${doc.name} (${doc._id})`);
  } else {
    Object.assign(doc, a);
    await doc.save();
    console.log(`[Author] Updated: ${doc.name} (${doc._id})`);
  }
  return doc;
}

async function upsertArticle(raw, authorDoc) {
  const data = { ...raw };
  data.author = {
    name: authorDoc.name,
    avatar: authorDoc.avatar || '',
    desc: authorDoc.desc || '',
    detail: authorDoc.detail || ''
  };
  data.authorId = authorDoc._id;
  if (!data.qa) data.qa = [];

  let doc = await Article.findOne({ slug: data.slug });
  let action = 'Created';
  if (!doc) {
    doc = new Article(data);
  } else {
    action = 'Updated';
    Object.assign(doc, data);
  }
  doc.updatedAt = new Date();
  await doc.save();
  console.log(`[Article] ${action}: ${doc.title} (slug=${doc.slug})`);
  return doc;
}

async function main() {
  console.log(`[Seed] Connecting to MongoDB: ${MONGODB_URL}`);
  await mongoose.connect(MONGODB_URL);
  console.log('[Seed] MongoDB connected.');

  try {
    const authors = [];
    for (const a of seedAuthors) {
      authors.push(await upsertAuthor(a));
    }
    console.log('');

    for (let i = 0; i < seedArticles.length; i++) {
      await upsertArticle(seedArticles[i], authors[i]);
    }

    console.log('\n[Seed] All done ✅');
  } finally {
    await mongoose.disconnect();
    console.log('[Seed] MongoDB disconnected.');
  }
}

main().catch(err => {
  console.error('[Seed] Failed:', err);
  process.exit(1);
});
